'use client';
import {useEffect,useRef,useState} from 'react';
import {usd} from '@/lib/pilot';
import {staffTestPaymentRequest} from '@/lib/staff-test-payment-request';
import {PaymentRecoveryPanel} from './payment-recovery-panel';
export function PrepareTestPayment({actor,tenant,property,reservation,disabled,canCancel=false}:{actor:string;tenant:string;property:string;reservation:string;disabled:boolean;canCancel?:boolean}){
 return <ScopedPaymentPreparation key={JSON.stringify([actor,tenant,property,reservation])} actor={actor} tenant={tenant} property={property} reservation={reservation} disabled={disabled} canCancel={canCancel}/>;
}
function ScopedPaymentPreparation({actor,tenant,property,reservation,disabled,canCancel}:{actor:string;tenant:string;property:string;reservation:string;disabled:boolean;canCancel:boolean}){
 const pending=useRef(false),request=useRef<AbortController|null>(null);
 useEffect(()=>()=>{request.current?.abort()},[]);
 const [busy,setBusy]=useState(false),[message,setMessage]=useState(''),[paidReady,setPaidReady]=useState(false);
 async function run(action:'staff_prepare'|'staff_cancel'|'staff_record'|'staff_refund',reason?:string){if(pending.current||disabled)return;pending.current=true;setBusy(true);setMessage('');const controller=new AbortController();request.current=controller;try{const d=await staffTestPaymentRequest(action,{actor,tenant,property,reservation,...(reason?{reason}:{})},30000,controller.signal);if(controller.signal.aborted)return;if(action==='staff_cancel'){if(d.test!==true)throw Error('Cancellation could not be verified. Retry cancellation.');setPaidReady(d.paid);setMessage(d.paid?'Payment already completed. Cancellation is not a refund; reconcile the receipt and review the payment in Stripe.':d.cancelled?'Test checkout cancelled. No refund was issued.':d.pending?'Cancellation pending. Retry cancellation to check and finish it.':'Cancellation could not be confirmed. Retry cancellation.');return}if(action==='staff_record'){if(d.test!==true||d.recorded!==true)throw Error('Folio reconciliation could not be verified. Refresh the folio.');setPaidReady(true);setMessage(d.replayed?'The existing Stripe test receipt is already in the folio. No duplicate was posted.':`Verified Stripe test payment of ${usd(d.amount)} recorded in the folio.`);return}if(action==='staff_refund'){if(d.test!==true)throw Error('Test refund could not be verified. Retry this same refund to check its status.');setMessage(d.refunded?d.replayed?`The existing full Stripe test refund of ${usd(d.amount)} is already reconciled to the folio.`:`Full Stripe test refund of ${usd(d.amount)} was issued and recorded in the folio.`:d.pending?'Stripe test refund is pending. Retry this same action to check and reconcile it.':'Stripe test refund status needs review.');return}setPaidReady(d.paid);setMessage(d.paid?'Stripe test payment confirmed. The folio has not changed yet. An owner or manager can reconcile the verified receipt below.':`Test checkout prepared for ${usd(d.amount)}. The guest can open it after submitting arrival details. No real money will be collected.`)}catch(e){if(!controller.signal.aborted)setMessage(e instanceof Error?e.message:'Payment test unavailable.')}finally{pending.current=false;if(!controller.signal.aborted)setBusy(false)}}
 function requestRefund(){if(busy||disabled)return;const reason=window.prompt('Reason for this full Stripe TEST refund (8–500 characters). No real money will be refunded.');if(reason===null)return;if(!window.confirm('Issue a full refund in Stripe test mode and record it against the original folio receipt? This cannot refund real money.'))return;void run('staff_refund',reason)}
 return <><div className="pilot-actions"><button type="button" className="secondary" disabled={disabled||busy} onClick={()=>void run('staff_prepare')}>{busy?'Working…':'Prepare Apple Pay / Google Pay test'}</button>{paidReady&&canCancel&&<button type="button" className="secondary" disabled={disabled||busy} onClick={()=>void run('staff_record')}>{busy?'Reconciling…':'Record verified test payment to folio'}</button>}{canCancel&&<><button type="button" className="secondary" disabled={disabled||busy} onClick={()=>void run('staff_cancel')}>Cancel / retry test checkout cancellation</button><button type="button" className="secondary" disabled={disabled||busy} onClick={requestRefund}>Issue / recover full Stripe test refund</button></>}{message&&<output aria-live="polite">{message}</output>}</div>{canCancel&&<PaymentRecoveryPanel key={`${actor}:${tenant}:${property}:${reservation}`} actor={actor} tenant={tenant} property={property} reservation={reservation} disabled={disabled||busy}/>}</>;
}
